<?php
/** Read-only communications overview, point-of-use help and one subject task. @package Booster_For_WooCommerce/admin */
defined('ABSPATH') || exit;
final class WCJ_Communications_Workspace {
 public static function data(){return require __DIR__.'/communications-workspace-groups.php';}
 public static function groups(){return self::data()['groups'];}
 public static function edition(){return WCJ_Communication_Subject_Job::edition();}
 public static function allowed($id){$core=WCJ_Job_Store::core();return current_user_can('manage_woocommerce')&&$core&&isset($core->all_modules[$id])&&(!function_exists('wcj_is_module_allowed_by_allowlist')||wcj_is_module_allowed_by_allowlist($id))&&(!wcj_is_module_enabled('modules_by_user_roles')||wcj_check_modules_by_user_roles($id));}
 public static function raw($key){global $wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",$key),ARRAY_A);if($wpdb->last_error){throw new RuntimeException('Saved communications settings could not be read.');}return $r?(string)$r['option_value']:null;}
 public static function flag($raw){return null===$raw?'Not stored':('yes'===$raw?'On':('no'===$raw?'Off':'Unrecognized saved value'));}
 public static function count_projection($raw,$one=false){if($one){return array('known'=>true,'count'=>1,'text'=>'One slot under this edition');}if(null===$raw){return array('known'=>true,'count'=>1,'text'=>'1 slot by default');}if(!is_string($raw)||!preg_match('/\A(?:0|[1-9][0-9]{0,8})\z/D',$raw)){return array('known'=>false,'count'=>0,'text'=>'Saved count needs full settings; not guessed or changed');}return array('known'=>true,'count'=>(int)$raw,'text'=>'Saved count: '.$raw);}
 public static function list_projection($raw){if(null===$raw||''===$raw){return array('known'=>true,'values'=>array());}if(!is_string($raw)||strlen($raw)>16384){return array('known'=>false,'values'=>array());}$v=@unserialize($raw,array('allowed_classes'=>false,'max_depth'=>2));if(!is_array($v)||count($v)>128||serialize($v)!==$raw){return array('known'=>false,'values'=>array());}foreach($v as $k=>$x){if(!is_string($x)||strlen($x)>200||1!==preg_match('//u',$x)||null!==ReflectionReference::fromArrayElement($v,$k)){return array('known'=>false,'values'=>array());}}return array('known'=>true,'values'=>array_values($v));}
 public static function custom_projection($raw){$bad=array('known'=>false,'enabled'=>'Unrecognized saved email settings','triggers'=>'Use full settings','recipient'=>'Use full settings');if(null===$raw){return array('known'=>true,'enabled'=>'Off by default','triggers'=>'No stored triggers','recipient'=>'No recipient saved. WooCommerce may send this email to your site admin address.');}if(!is_string($raw)||strlen($raw)>65536){return $bad;}$a=@unserialize($raw,array('allowed_classes'=>false,'max_depth'=>3));if(!is_array($a)||count($a)>40||serialize($a)!==$raw){return $bad;}foreach($a as $k=>$v){if(!is_string($k)||null!==ReflectionReference::fromArrayElement($a,$k)||(!is_string($v)&&!is_array($v))){return $bad;}if(is_array($v)){foreach($v as $j=>$x){if(!is_string($x)||null!==ReflectionReference::fromArrayElement($v,$j)){return $bad;}}}}$tr=$a['trigger']??array();$rec=$a['recipient']??'';return array('known'=>true,'enabled'=>self::flag($a['enabled']??null),'triggers'=>is_array($tr)?count($tr).' saved trigger choices':'Unrecognized trigger choice','recipient'=>is_string($rec)?(''===$rec?'Empty recipient; native fallback can use site admin':('%customer%'===$rec?'Customer token saved; actual event determines recipient':'A recipient expression is configured; addresses are kept in full settings')):'Unrecognized recipient value');}
 private static function configured($raw){return null===$raw?'Not stored':(''===$raw?'Saved empty':(strlen($raw)>65536||is_serialized($raw)?'Unrecognized or advanced saved value':'Configured; value remains in full settings'));}
 public static function url(){return admin_url('admin.php?page=wcj-communications');}
 public static function native_url($g,$slot=1){if('custom-message'===$g['id']){return admin_url('admin.php?page=wc-settings&tab=email&section=wc_email_wcj_custom_'.absint($slot));}return admin_url(wcj_admin_tab_url().'&section='.$g['module'].'&active_tab='.$g['native_tab']);}
 public static function link($url,$label){return '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($url).'">'.esc_html($label.' (new tab)').'</a>';}
 public static function entry(){foreach(self::groups() as $g){if(self::allowed($g['module'])){echo '<p><a href="'.esc_url(self::url()).'">Customer communications: email wording, routing and reminders</a></p>';return;}}}
 private static function custom_slot(){if(!self::allowed('emails')){return array('known'=>false,'count'=>0,'slot'=>0,'text'=>'Access is unavailable');}$c=self::count_projection(self::raw('wcj_emails_custom_emails_total_number'),'free'===self::edition());$v=$_GET['custom_slot']??'1';$slot=is_string($v)&&preg_match('/\A[1-9][0-9]{0,8}\z/D',$v)?(int)$v:0;$c['slot']=$c['known']&&$slot<=$c['count']?$slot:0;return $c;}
 public static function help($section='',$module='',$selected=array(),$slot=1){$ed=self::edition();foreach(self::groups() as $g){if(($section&&$section!==$g['section'])||($module&&$module!==$g['module'])||($selected&&!in_array($g['id'],$selected,true))||empty($g['members'][$ed])||!self::allowed($g['module'])){continue;}$url=self::native_url($g,$slot);if('custom-message'===$g['id']&&(!$slot||'yes'!==self::raw('wcj_emails_enabled'))){$url=admin_url('admin.php?page=wc-settings&tab=email');}echo '<article class="wcj-communications-group" data-communications-group="'.esc_attr($g['id']).'"><h3>'.esc_html($g['label']).'</h3><p>'.esc_html($g['context']).'</p><p>'.self::link($url,'Full settings').' | '.self::link($g['guide'],'Guide: '.$g['label']).'</p><details><summary>Settings covered</summary><ul>';foreach($g['members'][$ed] as $m){echo '<li>'.esc_html($m['label'].($m['locked']?' (locked in this edition)':'')).'</li>';}echo '</ul></details>';if(in_array($g['id'],array('cart-report','stock-subscribers'),true)){if('yes'===self::raw('wcj_'.$g['module'].'_enabled')){$tab='cart-report'===$g['id']?'cart_abandonment':'back_in_stock_subscribers';echo '<p>'.self::link(admin_url('admin.php?page=wcj-tools&tab='.$tab.'&wcj_tools_nonce='.wp_create_nonce('wcj_tools')),'Open existing report or list').'</p>';}else{echo '<p>The module is not saved as on. Its report or list remains in full settings.</p>';}}echo '</article>';}}
 public static function screen_help(){if(!current_user_can('manage_woocommerce')){return;}$page=$_GET['page']??'';$section=$_GET['section']??'';$tab=$_GET['tab']??'';$active=$_GET['active_tab']??'';if(!is_string($page)||!is_string($section)||!is_string($tab)||!is_string($active)){return;}$mod='';$pick=array();$slot=1;
  if('wcj-plugins'===$page&&in_array($section,array_unique(array_column(self::groups(),'module')),true)&&self::allowed($section)){$mod=$section;if($active){foreach(self::groups() as $g){if($g['module']===$mod&&$g['native_tab']===$active){$pick[]=$g['id'];}}}}
  elseif('wc-settings'===$page&&'email'===$tab){if(preg_match('/\Awc_email_wcj_custom_([1-9][0-9]{0,8})\z/D',$section,$m)&&self::allowed('emails')){$c=self::count_projection(self::raw('wcj_emails_custom_emails_total_number'),'free'===self::edition());if(!$c['known']||(int)$m[1]>$c['count']){return;}$slot=(int)$m[1];$pick=array('custom-message');}elseif(''===$section&&self::allowed('email_options')){$pick=array('forwarding');}else{return;}}
  elseif('wcj-tools'===$page&&in_array($tab,array('cart_abandonment','back_in_stock_subscribers'),true)){$mod='cart_abandonment'===$tab?'cart_abandonment':'back_in_stock_notifications';if(!self::allowed($mod)){return;}$pick=array('cart_abandonment'===$tab?'cart-report':'stock-subscribers');}
  else{$screen=get_current_screen();if($screen&&'users'===$screen->id&&self::allowed('emails_verification')){$pick=array('verification-access','verification-notices');}elseif($screen&&in_array($screen->id,array('shop_order','edit-shop_order','woocommerce_page_wc-orders'),true)&&self::allowed('emails')){$pick=array('custom-message');}else{return;}}
  echo '<div class="notice notice-info wcj-communications-context"><p><a href="'.esc_url(self::url()).'">Customer communications workspace</a>. Help opens separately without changing this screen.</p><details><summary>Message settings and actions: effects and guidance</summary>';self::help('',$mod,$pick,$slot);echo '</details></div>';
 }
 private static function summaries($section){$rows=array();
  if('Order emails and routing'===$section){if(self::allowed('emails')){$c=self::custom_slot();$rows['Custom Emails module']=self::flag(self::raw('wcj_emails_enabled'));$rows['Custom email slots']=$c['text'];if($c['slot']){$p=self::custom_projection(self::raw('woocommerce_wcj_custom_'.$c['slot'].'_settings'));$rows['Email #'.$c['slot'].' enabled']=$p['enabled'];$rows['Email #'.$c['slot'].' triggers']=$p['triggers'];$rows['Email #'.$c['slot'].' recipient']=$p['recipient'];}}if(self::allowed('email_options')){$rows['Email Options module']=self::flag(self::raw('wcj_email_options_enabled'));$rows['CC field']=self::configured(self::raw('wcj_emails_cc_email'));$rows['BCC field']=self::configured(self::raw('wcj_emails_bcc_email'));$st=self::list_projection(self::raw('wcj_emails_forwarding_enable_order_status'));$rows['Order-status restriction']='free'===self::edition()?'Locked in Free; supplied unrestricted behavior':($st['known']?(count($st['values']).' saved status choices; empty imposes no order-status restriction'):'Saved restriction needs full settings');$rows['Product information addition']=self::flag(self::raw('wcj_product_info_in_email_order_item_name_enabled'));}}
  if('Account verification'===$section&&self::allowed('emails_verification')){$rows['Verification module']=self::flag(self::raw('wcj_emails_verification_enabled'));$rows['Existing-account coverage']=self::flag(self::raw('wcj_emails_verification_already_registered_enabled'));$rows['Global login prevention']=self::flag(self::raw('wcj_emails_verification_prevent_user_login'));$roles=self::list_projection(self::raw('wcj_emails_verification_skip_user_roles'));$rows['Skipped roles']=null===self::raw('wcj_emails_verification_skip_user_roles')?'Not stored; supplied role is administrator':($roles['known']?count($roles['values']).' saved role choices':'Saved role choices need full settings');$rows['Outgoing verification wording']='free'===self::edition()?'Supplied Free subject, body and plain template':'Configured in the existing Plus or Elite email editor';}
  if('Cart reminders'===$section&&self::allowed('cart_abandonment')){$rows['Cart Abandonment module']=self::flag(self::raw('wcj_cart_abandonment_enabled'));$rows['First reminder enabled']=self::flag(self::raw('wcj_ca_email_template_enabled_1'));$c=self::count_projection(self::raw('wcj_ca_email_template_total_number'),'elite'!==self::edition());$rows['Reminder slots']=$c['text'];$t=self::raw('wcj_ca_email_trigger_time_1');$u=self::raw('wcj_ca_email_trigger_time_type_1');$rows['First reminder delay']=null===$t||null===$u?'Incomplete stored timing; see full settings':(strlen($t)<=32&&preg_match('/\A[0-9]+(?:\.[0-9]+)?\z/D',$t)&&in_array($u,array('day','minute','hour'),true)?$t.' '.$u.' (saved delay, not a delivery guarantee)':'Saved timing needs full settings');$discount=self::raw('wcj_ca_email_discount_type_1');$rows['First reminder discount']=null===$discount?'Not stored; do not infer coupon behavior':('no'===$discount?'No discount saved':(in_array($discount,array('percent','fixed_cart'),true)?'A discount type is saved; scheduled attempts may create coupons':'Unrecognized saved discount'));$rows['Auto-apply coupon']=self::flag(self::raw('wcj_ca_auto_apply_coupon_1'));$rows['Native test email']='elite'===self::edition()?'Available only in full settings; real outbound test to the current authorized user':'Not available in this edition';}
  if('Stock alerts'===$section&&self::allowed('back_in_stock_notifications')){$rows['Stock alerts module']=self::flag(self::raw('wcj_back_in_stock_notifications_enabled'));$rows['Product-page form']=self::flag(self::raw('wcj_back_in_stock_single_enabled'));$rows['Product-list form']=self::flag(self::raw('wcj_back_in_stock_archives_enabled'));$rows['Subscription confirmation']=self::flag(self::raw('wcj_back_in_stock_subscription_success_email'));$rows['Administrator notification']=self::flag(self::raw('wcj_back_in_stock_admin_subscribed_email'));$rows['Spam protection']=self::flag(self::raw('wcj_back_in_stock_recaptcha_enabled'));$rows['In-stock checkbox']=self::flag(self::raw('wcj_back_in_stock_instock_email')).'; not a reliable pause control';$rows['Subscriber status']='No contact records loaded; notified does not prove delivery';}
  return $rows;
 }
 public static function register(){if(current_user_can('manage_woocommerce')){add_submenu_page('woocommerce','Customer communications','Customer communications','manage_woocommerce','wcj-communications',array(__CLASS__,'render'));}}
 public static function render(){if(!current_user_can('manage_woocommerce')){wp_die('Ask an administrator for access.');}wp_enqueue_style('wcj-communications-workspace',wcj_plugin_url().'/assets/css/admin/wcj-communications-workspace.css',array(),'1.0');echo '<div class="wrap wcj-communications-workspace"><h1>Customer communications</h1><p>Understand saved message settings and change only what you need. This workspace does not activate modules, send messages, subscribe shoppers or change account access. Existing site setup may still run when WordPress loads.</p><p>Saved choices below are not delivery history or a prediction of the final message. Integrations and mail systems can change behavior.</p>';
  try{$c=self::custom_slot();$lanes=array('Order emails and routing','Account verification','Cart reminders','Stock alerts');echo '<nav aria-label="Communication settings sections">';foreach($lanes as $i=>$lane){$r=self::summaries($lane);if($r){echo '<a href="#wcj-communications-section-'.$i.'">'.esc_html($lane).'</a> ';}}echo '</nav>';
   if(self::allowed('cart_abandonment')){self::form();}
   foreach($lanes as $i=>$lane){$rows=self::summaries($lane);if(!$rows){if('Stock alerts'===$lane&&'elite'!==self::edition()){echo '<p>Stock alerts are available in Elite.</p>';}continue;}echo '<details class="wcj-communications-section" id="wcj-communications-section-'.$i.'"'.('Cart reminders'===$lane?' open':'').'><summary><h2>'.esc_html($lane).'</h2></summary><section class="wcj-communications-current"><h3>Saved configuration</h3><dl>';foreach($rows as $label=>$value){echo '<div><dt>'.esc_html($label).'</dt><dd>'.esc_html($value).'</dd></div>';}echo '</dl></section>';
    if('Order emails and routing'===$lane&&self::allowed('emails')&&$c['known']&&$c['count']>0){echo '<form method="get"><input type="hidden" name="page" value="wcj-communications"><label for="wcj-custom-slot">Custom email slot</label> <input type="number" id="wcj-custom-slot" name="custom_slot" min="1" max="'.esc_attr($c['count']).'" value="'.esc_attr($c['slot']?:1).'"> <button class="button" type="submit">Show saved slot</button></form><p>Choose any configured slot; this view shows one at a time. The email must be enabled through its existing settings before its triggers can send.</p>';if(!$c['slot']){echo '<p role="status">That slot is outside the saved count. Select a valid slot; no slot was guessed.</p>';}}
    self::help($lane,'',array(),$c['slot']);echo '</details>';}
  }catch(Throwable $e){echo '<p role="alert">'.esc_html($e->getMessage()).'</p>';}echo '</div>';
 }
 private static function form(){$t=self::data()['task'];$module=self::raw('wcj_cart_abandonment_enabled');$enabled=self::raw('wcj_ca_email_template_enabled_1');wp_enqueue_script('wcj-communications-workspace',wcj_plugin_url().'/assets/js/admin/wcj-communications-workspace.js',array(),'1.0',true);$nonces=array();foreach(WCJ_Communication_Subject_Job::OPS as $op){$nonces[$op]=wp_create_nonce('wcj_communication_subject_'.$op);}wp_localize_script('wcj-communications-workspace','wcjCommunicationsWorkspace',array('url'=>admin_url('admin-ajax.php'),'nonces'=>$nonces,'type'=>'first'));
 echo '<form class="wcj-communication-subject" data-field="subject"><h2>'.esc_html($t['title']).'</h2><p>'.esc_html($t['intro']).'</p><p>Saved module state: <strong>'.esc_html(self::flag($module)).'</strong>. Saved first reminder state: <strong>'.esc_html(self::flag($enabled)).'</strong>.</p><p>'.esc_html('yes'===$module&&'yes'===$enabled?$t['active']:'Saving a subject does not change these states or enable a reminder.').'</p><label for="wcj-first-subject">First reminder subject</label><input id="wcj-first-subject" name="value" type="text" disabled aria-describedby="wcj-subject-hint"><p id="wcj-subject-hint">'.esc_html($t['tokens']).'</p><details><summary>Subject limits and recovery</summary><p>'.esc_html($t['limit']).'</p><p>'.esc_html($t['recovery']).'</p><p>'.esc_html($t['readback']).'</p></details><p>'.esc_html($t['sample']).' <span class="wcj-communications-example"></span></p><p class="wcj-communications-saved"></p><p class="wcj-communications-status" role="status" aria-live="polite">Loading saved subject...</p><button class="button button-primary" type="submit" disabled>Save subject</button> <button class="button wcj-communications-restore" type="button" disabled>Restore previous</button> <button class="button wcj-communications-reload" type="button">Discard draft and reload</button><p>'.self::link(admin_url(wcj_admin_tab_url().'&section=cart_abandonment&active_tab=wcj_cart_abandonment_email_templates_tab'),'Full reminder settings').'</p></form>';
 }
}
add_action('admin_menu',array('WCJ_Communications_Workspace','register'),99);
add_action('admin_notices',array('WCJ_Communications_Workspace','screen_help'),41);
